def shift(a,dr,dc,wrap=False):
 if wrap:return np.roll(a,(dr,dc),(0,1))
 o=np.zeros_like(a)
 for r in range(a.shape[0]):
  for c in range(a.shape[1]):
   rr=r-dr; cc=c-dc
   if 0<=rr<a.shape[0] and 0<=cc<a.shape[1]:o[r,c]=a[rr,cc]
